mapper.insert:
INSERT INTO svc_chat_list (
    ownr_nm,
    mbr_id,
    vhcl_sn
) VALUES (
    #{currentOwnrNm},
    #{currentUserId},
    #{vhclSn}
)

mapper.select:
select chat_cn_sn, chat_sn, ownr_nm, mbr_id, vhcl_sn, qstn_cn, ans_cn, JSON_EXTRACT(ans_cn, '$.answer') as answer, JSON_EXTRACT(ans_cn, '$.error') as error, JSON_EXTRACT(ans_cn, '$.recommended_questions') as recommend, evl, reg_dt from svc_chat_cn_list where 1=1 and chat_sn = #{chatSn}
AND ownr_nm = #{currentOwnrNm}
order by chat_cn_sn asc

mapper.update:
UPDATE svc_chat_cn_list
	SET evl = #{evl}
WHERE chat_cn_sn = #{chatCnSn}

mapper.select:
select chat_cn_sn, chat_sn, ifnull(ownr_nm,'') as ownr_nm, mbr_id, vhcl_sn, qstn_cn, ans_cn, JSON_EXTRACT(ans_cn, '$.answer') as answer, JSON_EXTRACT(ans_cn, '$.error') as error, JSON_EXTRACT(ans_cn, '$.recommended_questions') as recommend, ifnull(evl,'') as evl, reg_dt from svc_chat_cn_list where 1=1 AND (
ownr_nm IN
#{ownr}
or ownr_nm is null or ownr_nm = ''
)
and ownr_nm = #{ownrNm}
AND reg_dt >= CONCAT(#{startDt}, ' 00:00:00') AND reg_dt <= CONCAT(#{endDt}, ' 23:59:59')
order by reg_dt desc
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

select count(*) from svc_chat_cn_list where 1=1 AND (
ownr_nm IN
#{ownr}
or ownr_nm is null or ownr_nm = ''
)
and ownr_nm = #{ownrNm}
AND reg_dt >= CONCAT(#{startDt}, ' 00:00:00') AND reg_dt <= CONCAT(#{endDt}, ' 23:59:59')

SELECT CASE WHEN #{dateType} = 'date' THEN DATE(reg_dt) WHEN #{dateType} = 'month' THEN DATE_FORMAT(reg_dt, '%Y-%m') END AS date, COUNT(reg_dt) as cnt FROM svc_chat_cn_list WHERE 1=1 AND (
ownr_nm IN
#{ownr}
OR ownr_nm IS NULL or ownr_nm = ''
)
AND ownr_nm = #{ownrNm}
AND reg_dt >= CONCAT(#{startDt}, ' 00:00:00') AND reg_dt <= CONCAT(#{endDt}, ' 23:59:59')
GROUP BY CASE WHEN #{dateType} = 'date' THEN DATE(reg_dt) WHEN #{dateType} = 'month' THEN DATE_FORMAT(reg_dt, '%Y-%m') END
